using System.Data;using Microsoft.Data.SqlClient;using PizzaSatinAlmaYonetimi.Web.Data;using PizzaSatinAlmaYonetimi.Web.Models;
namespace PizzaSatinAlmaYonetimi.Web.Services;
public sealed class BildirimService(ISqlConnectionFactory factory):IBildirimService
{
 public async Task<BildirimViewModel>GetirAsync(int uid,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var cmd=Komut(c,"dbo.sp_KullaniciBildirimleri");cmd.Parameters.Add("@KullaniciID",SqlDbType.Int).Value=uid;await using var r=await cmd.ExecuteReaderAsync(ct);var l=new List<BildirimSatiri>();while(await r.ReadAsync(ct))l.Add(new(r.GetInt32("BildirimID"),r.GetString("Baslik"),r.GetString("Mesaj"),r.GetString("OkunmaDurumu"),r.GetDateTime("OlusturmaTarihi"),r.IsDBNull("OkunmaTarihi")?null:r.GetDateTime("OkunmaTarihi")));await r.CloseAsync();await using var say=Komut(c,"dbo.sp_OkunmamisBildirimSayisi");say.Parameters.Add("@KullaniciID",SqlDbType.Int).Value=uid;var count=Convert.ToInt32(await say.ExecuteScalarAsync(ct));return new(){Bildirimler=l,OkunmamisSayisi=count};}
 public async Task OkunduYapAsync(int id,int uid,CancellationToken ct){await Calistir("dbo.sp_BildirimiOkunduYap",uid,ct,id);await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var kontrol=new SqlCommand("SELECT COUNT(1) FROM dbo.Bildirimler WHERE BildirimID=@BildirimID AND KullaniciID=@KullaniciID AND OkunduMu=1 AND OkunmaTarihi IS NOT NULL",c);kontrol.Parameters.Add("@BildirimID",SqlDbType.Int).Value=id;kontrol.Parameters.Add("@KullaniciID",SqlDbType.Int).Value=uid;if(Convert.ToInt32(await kontrol.ExecuteScalarAsync(ct))!=1)throw new InvalidOperationException("Bildirim okundu olarak işaretlenemedi.");}public Task TumunuOkunduYapAsync(int uid,CancellationToken ct)=>Calistir("dbo.sp_TumBildirimleriOkunduYap",uid,ct,null);
 private async Task Calistir(string ad,int uid,CancellationToken ct,int? id){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var cmd=Komut(c,ad);if(id.HasValue)cmd.Parameters.Add("@BildirimID",SqlDbType.Int).Value=id;cmd.Parameters.Add("@KullaniciID",SqlDbType.Int).Value=uid;await cmd.ExecuteNonQueryAsync(ct);}private static SqlCommand Komut(SqlConnection c,string a)=>new(a,c){CommandType=CommandType.StoredProcedure};
}
